/**
 * Unit tests for gh-label-enforcer hook
 *
 * Tests auto-correct behavior for `gh issue create` without --label,
 * advisory behavior for `gh pr create` without --label, out-of-scope
 * skip for explicit repo targets, and silent pass-through for all
 * other commands.
 *
 * Issues #916, #3389
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import type { HookInput } from '../../types.js';

// ---------------------------------------------------------------------------
// Mocks
// ---------------------------------------------------------------------------

vi.mock('../../lib/common.js', async () => {
  const actual = await vi.importActual<typeof import('../../lib/common.js')>('../../lib/common.js');
  return {
    ...actual,
    logHook: vi.fn(),
    logPermissionFeedback: vi.fn(),
    outputSilentSuccess: vi.fn(() => ({ continue: true, suppressOutput: true })),
    outputDeny: vi.fn((msg: string) => ({
      continue: false,
      stopReason: msg,
      hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: msg },
    })),
    outputAllowWithContext: vi.fn((ctx: string) => ({
      continue: true,
      suppressOutput: true,
      hookSpecificOutput: { additionalContext: ctx, hookEventName: 'PreToolUse' },
    })),
  };
});

import { ghLabelEnforcer } from '../../pretool/bash/gh-label-enforcer.js';
import { outputSilentSuccess, outputDeny, outputAllowWithContext } from '../../lib/common.js';
import { createTestContext } from '../fixtures/test-context.js';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function createBashInput(command: string, overrides: Partial<HookInput> = {}): HookInput {
  return {
    tool_name: 'Bash',
    session_id: 'test-session-123',
    project_dir: '/test/project',
    tool_input: { command },
    ...overrides,
  };
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

let testCtx: ReturnType<typeof createTestContext>;
describe('gh-label-enforcer', () => {
  beforeEach(() => {
    testCtx = createTestContext();
    vi.clearAllMocks();
  });

  // -------------------------------------------------------------------------
  // Pass-through — commands that are not gh issue/pr create
  // -------------------------------------------------------------------------

  describe('non-matching commands', () => {
    it.each([
      'gh issue list',
      'gh issue view 42',
      'gh pr list',
      'gh pr view 42',
      'gh pr merge 42',
      'git commit -m "test"',
      'npm run build',
      '',
    ])('returns silent success for: %s', (command) => {
      const input = createBashInput(command);
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
      expect(outputSilentSuccess).toHaveBeenCalled();
    });

    it('returns silent success when tool_input.command is undefined', () => {
      const input: HookInput = {
        tool_name: 'Bash',
        session_id: 'test-session-123',
        project_dir: '/test/project',
        tool_input: {},
      };
      const result = ghLabelEnforcer(input, testCtx);
      expect(result.continue).toBe(true);
    });
  });

  // -------------------------------------------------------------------------
  // gh issue create — auto-correct behavior (#3389, replaced the old deny)
  // -------------------------------------------------------------------------

  describe('gh issue create — without --label (auto-correct)', () => {
    it('auto-appends an inferred --label via updatedInput instead of denying', () => {
      const input = createBashInput('gh issue create --title "Fix auth bug"');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
      expect(outputDeny).not.toHaveBeenCalled();
      expect(result.hookSpecificOutput?.updatedInput).toEqual({
        command: 'gh issue create --title "Fix auth bug" --label bug',
      });
    });

    it('sets no permissionDecision — the rewrite must not grant or deny', () => {
      // updatedInput rides through the normal permission prompt. Setting
      // 'allow' here would skip the prompt as a side effect of a labelling
      // nit — the same trap the compound advisory below documents.
      const input = createBashInput('gh issue create --title "Fix auth bug"');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.hookSpecificOutput?.permissionDecision).toBeUndefined();
    });

    it('preserves sibling tool_input fields in updatedInput', () => {
      const input = createBashInput('gh issue create --title "Fix crash"');
      input.tool_input.description = 'File crash issue';
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.hookSpecificOutput?.updatedInput?.description).toBe('File crash issue');
    });

    it.each([
      ['gh issue create --title "Fix login crash"', 'bug'],
      ['gh issue create --title "Update README typos"', 'docs'],
      ['gh issue create --title "Add dark mode support"', 'enhancement'],
      ['gh issue create --title "Weekly dependency sweep"', 'chore'],
    ])('infers the label from the title: %s -> %s', (command, label) => {
      const input = createBashInput(command);
      const result = ghLabelEnforcer(input, testCtx);

      const rewritten = result.hookSpecificOutput?.updatedInput as { command: string } | undefined;
      expect(rewritten?.command).toBe(`${command} --label ${label}`);
    });

    it('explains the rewrite in additionalContext', () => {
      const input = createBashInput('gh issue create --title "Fix auth bug"');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.hookSpecificOutput?.additionalContext).toContain('Auto-appended --label bug');
    });

    it('logs the auto-correct', () => {
      const input = createBashInput('gh issue create --title "Broken build"');
      ghLabelEnforcer(input, testCtx);

      expect(testCtx.log).toHaveBeenCalledWith(
        'gh-label-enforcer',
        expect.stringContaining('Auto-appended'),
      );
    });
  });

  // -------------------------------------------------------------------------
  // Explicit repo target — out of scope (#3389)
  // -------------------------------------------------------------------------

  describe('explicit repo target — skipped entirely', () => {
    it.each([
      'gh issue create --repo herdrdev/herdr --title "Fix crash"',
      'gh issue create -R other/repo --title "Fix crash"',
      'gh issue create --repo=other/repo --title "Fix crash"',
      'GH_REPO=other/repo gh issue create --title "Fix crash"',
    ])('skips enforcement for: %s', (command) => {
      // Label taxonomies are repo-local. This hook cannot verify a foreign
      // repo has our labels, and appending one that does not exist turns a
      // nit into a hard gh failure — the 2026-08-10 misfire that filed #3389.
      const input = createBashInput(command);
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
      expect(outputSilentSuccess).toHaveBeenCalled();
      expect(result.hookSpecificOutput?.updatedInput).toBeUndefined();
      expect(outputDeny).not.toHaveBeenCalled();
    });

    it('skips the PR advisory when --repo targets another repo', () => {
      const input = createBashInput('gh pr create --repo other/repo --title "My PR"');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
      expect(outputAllowWithContext).not.toHaveBeenCalled();
    });
  });

  describe('gh issue create — with --label (allowed)', () => {
    it('allows gh issue create with --label flag', () => {
      const input = createBashInput('gh issue create --title "Fix auth bug" --label bug');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
      expect(outputSilentSuccess).toHaveBeenCalled();
    });

    it('allows gh issue create with --label followed by quoted value', () => {
      const input = createBashInput('gh issue create --title "Feature" --label "enhancement"');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
    });

    it('allows gh issue create with -l shorthand', () => {
      const input = createBashInput('gh issue create --title "Chore" -l chore');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
      expect(outputSilentSuccess).toHaveBeenCalled();
    });

    it('allows gh issue create with label before title', () => {
      const input = createBashInput('gh issue create --label bug --title "Crash on login"');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
    });
  });

  // -------------------------------------------------------------------------
  // gh pr create — advisory behavior (warn, never block)
  // -------------------------------------------------------------------------

  describe('gh pr create — without --label', () => {
    it('returns advisory context (not a block) for gh pr create without --label', () => {
      const input = createBashInput('gh pr create --title "My PR" --base main');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
      expect(outputAllowWithContext).toHaveBeenCalled();
      expect(outputDeny).not.toHaveBeenCalled();
    });

    it('advisory message mentions --label', () => {
      const input = createBashInput('gh pr create --title "My PR"');
      ghLabelEnforcer(input, testCtx);

      const ctxCall = vi.mocked(outputAllowWithContext).mock.calls[0][0];
      expect(ctxCall).toContain('--label');
    });

    it('logs advisory for pr without label', () => {
      const input = createBashInput('gh pr create --title "My PR"');
      ghLabelEnforcer(input, testCtx);

      expect(testCtx.log).toHaveBeenCalledWith(
        'gh-label-enforcer',
        expect.stringContaining('Advisory'),
      );
    });
  });

  describe('gh pr create — with --label (silent)', () => {
    it('returns silent success for gh pr create with --label', () => {
      const input = createBashInput('gh pr create --title "My PR" --label enhancement');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
      expect(outputSilentSuccess).toHaveBeenCalled();
      expect(outputAllowWithContext).not.toHaveBeenCalled();
    });

    it('returns silent success for gh pr create with -l shorthand', () => {
      const input = createBashInput('gh pr create --title "My PR" -l bug');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
    });
  });

  // -------------------------------------------------------------------------
  // Edge cases
  // -------------------------------------------------------------------------

  describe('edge cases', () => {
    it('advises rather than blocks when gh issue create is part of a compound command', () => {
      // This command is COMPOUND, and that is the whole point. A PreToolUse deny
      // aborts before execution, so blocking here would throw away every earlier
      // segment of the chain — the #3283 report, where a heredoc that wrote the
      // file the second half needed never ran, and the natural retry then failed
      // for an unrelated reason.
      const input = createBashInput('gh issue create --title "A" && gh pr create --title "B"');
      const result = ghLabelEnforcer(input, testCtx);

      // Advisory, not a block: a missing label is a policy nit, not a hazard.
      expect(result.continue).toBe(true);

      // An advisory must INFORM without GRANTING. outputAllowWithContext would
      // set permissionDecision:'allow' and silently skip the permission prompt
      // as a side effect of a labelling nit, so assert we did not do that.
      expect(result.hookSpecificOutput?.permissionDecision).not.toBe('allow');
    });

    it('still auto-corrects a simple gh issue create with no --label', () => {
      // The compound carve-out above must not leak into the simple case, which
      // is the one the policy actually exists to enforce. A simple command is
      // enforced by rewriting it with an inferred label (#3389), not by
      // denying it — the policy lands either way, without destroying the turn.
      const input = createBashInput('gh issue create --title "A"');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
      expect(result.hookSpecificOutput?.updatedInput).toBeDefined();
      expect(outputDeny).not.toHaveBeenCalled();
    });

    it('does not falsely match "gh issue created" (past tense)', () => {
      // "gh issue created" does NOT match /gh\s+issue\s+create/ with word boundary
      const input = createBashInput('echo "gh issue created successfully"');
      const result = ghLabelEnforcer(input, testCtx);

      // The regex /gh\s+issue\s+create/ matches the substring "gh issue create" in "created"
      // This is intentional — the hook is conservative (false positive acceptable)
      expect(result.continue).toBeDefined(); // just ensure no crash
    });

    it('handles multiline command', () => {
      const input = createBashInput('gh issue create \\\n  --title "Bug" \\\n  --label bug');
      const result = ghLabelEnforcer(input, testCtx);

      expect(result.continue).toBe(true);
    });
  });
});
